<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';
use Kulturhus\Verein\{Database,Registry,MembershipApplications};
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);$db->exec("INSERT INTO clubs VALUES('a','Test'),('b','Other');INSERT INTO actors(id,club_id,role) VALUES('s','a','members'),('e','a','editor');INSERT INTO contacts(id,club_id,kind,name) VALUES('p','a','person','Test Elternteil'),('c','a','person','Test Kind'),('x','b','person','Fremd')");
$db->exec("UPDATE actors SET is_superuser=1 WHERE id IN ('s')");
$n=0;function ok(bool $v,string $label):void{global $n;if(!$v)throw new RuntimeException($label);++$n;echo "PASS $label\n";}
function denied(callable $f,string $label):void{try{$f();}catch(DomainException){ok(true,$label);return;}throw new RuntimeException($label);}
$r=new Registry($db,'s');$r->assignFamily('p','','new','Familie Test');$f=$r->family('p');$r->assignFamily('c','',$f['id']);$f=$r->family('c');ok(count($f['people'])===2&&$f['payer_contact_id']==='p','two profiles share one payer');
denied(fn()=>$r->assignFamily('p',$f['id'],''),'payer cannot leave accidentally');denied(fn()=>$r->assignFamily('c','',''),'stale assignment rejected');denied(fn()=>$r->saveFamily('c',$f['version'],'Test','x'),'foreign payer rejected');denied(fn()=>(new Registry($db,'e'))->family('c'),'editor cannot read family');
$r->saveFamily('c',$f['version'],'Familie Test','c');$r->assignFamily('p',$f['id'],'');ok($r->family('p')===null&&count($r->family('c')['people'])===1,'explicit payer change allows reassignment');
$i=new MembershipApplications($db,'a','s');$config=$i->settings()['config'];$config['enabled']=true;$i->saveSettings($config,0);$key=bin2hex(random_bytes(16));$answers=['first_name'=>'Digital','last_name'=>'Testfamilie','email'=>'digital@example.invalid','birthday'=>'1990-01-02','address'=>'Testweg 1','membership_type'=>'family','family_members'=>'Weitere Testperson'];
$id=$i->submit($answers,$key,1,true);$i->submit($answers,$key,1,true);ok((int)$db->query('SELECT COUNT(*) FROM document_files')->fetchColumn()===1,'repeated submission archives exactly one PDF');
$pdf=$db->query('SELECT bytes FROM document_files')->fetchColumn();ok(str_starts_with($pdf,'%PDF-'),'digital submission produces actual PDF');$a=json_decode($i->application($id)['answers'],true);ok($a['annual_fee_cents']===7200,'family tariff snapshotted at submission');
$c=$i->review($id,1,'accepted','Vorstandsbeschluss als Test dokumentiert','T100','2026-09-05',externalDecision:true,decisionDate:'2026-09-05',familyTarget:'new');ok($r->family($c)['payer_contact_id']===$c,'accepted family application links member and payer');ok((int)$db->query("SELECT COUNT(*) FROM document_links WHERE source_type='contact'")->fetchColumn()===1,'original PDF linked to accepted member');
$before=(int)$db->query('SELECT COUNT(*) FROM membership_applications')->fetchColumn();$db->exec("CREATE TRIGGER fail_document BEFORE INSERT ON document_files FOR EACH ROW BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='test'; END");try{$i->submit($answers,bin2hex(random_bytes(16)),1,true);throw new RuntimeException('Expected archive failure');}catch(PDOException){}ok((int)$db->query('SELECT COUNT(*) FROM membership_applications')->fetchColumn()===$before,'archive failure rolls back whole submission');
$db->exec("INSERT INTO actor_capabilities VALUES('s','local_finance')");$finance=new \Kulturhus\Verein\Finance($db,'s');$family=$r->family($c);$entry=$finance->createAnnualContribution($c,2026,$family['id']);ok($finance->entry($entry)['amount_cents']===7200,'family charged 72 EUR once');ok($finance->createAnnualContribution($c,2026,$family['id'])===$entry,'repeated annual charge reuses entry');
file_put_contents(__DIR__.'/../../.local/vereinsverwaltung/application-pdf-test.pdf',$pdf);echo "$n family/PDF checks passed\n";
